"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/data-density-control.css";
import { cn } from "../../lib/cn";
import { SegmentedControl, type SegmentedControlOption } from "./segmented-control";

export type DataDensity = "compact" | "default" | "comfortable";

export type DataDensityControlProps = {
  value?: DataDensity;
  defaultValue?: DataDensity;
  onValueChange?: (value: DataDensity) => void;
  label?: string;
  className?: string;
};

const densityOptions: readonly SegmentedControlOption[] = [
  { value: "compact", label: "Compact" },
  { value: "default", label: "Default" },
  { value: "comfortable", label: "Comfortable" },
];

export function DataDensityControl({ value, defaultValue = "default", onValueChange, label = "Row density", className }: DataDensityControlProps) {
  return (
    <div className={cn("whatiuse-data-density-control", className)}>
      <SegmentedControl
        label={label}
        options={densityOptions}
        value={value}
        defaultValue={defaultValue}
        size="small"
        onValueChange={(nextValue) => {
          if (nextValue) onValueChange?.(nextValue as DataDensity);
        }}
      />
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-data-density-control {
  display: inline-flex;
  min-width: 0;
}

.whatiuse-data-density-control .whatiuse-segmented-control { padding: 2px; }

.whatiuse-data-density-control .whatiuse-segmented-control__item { min-width: 0; padding-inline: 8px; }
}
